import numpy as np
def read_xyz(fn):
    with open(fn) as f: lines=f.read().splitlines()
    n=int(lines[0]); at=[]
    for ln in lines[2:2+n]:
        p=ln.split(); at.append((p[0],np.array([float(p[1]),float(p[2]),float(p[3])])))
    return at
at=read_xyz('opt3.xyz')
nA=29; nB=16
groups={'A':list(range(1,1+nA)),'B':list(range(1+nA,1+nA+nB)),'C':list(range(1+nA+nB,len(at)))}
for x in groups:
    for y in groups:
        if y<=x: continue
        mind=1e9; pair=None
        for i in groups[x]:
            for j in groups[y]:
                dd=np.linalg.norm(at[i][1]-at[j][1])
